<?php
require_once __DIR__.'/includes/functions.php';require_login();$pageTitle='Payments — DriveEase';$uid=(int)current_user()['id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rid=(int)($_POST['reservation_id']??0);$method=$_POST['method']??'Demo record';$s=db()->prepare("SELECT * FROM reservations WHERE id=? AND customer_id=? AND status='confirmed'");$s->execute([$rid,$uid]);$res=$s->fetch();if(!$res)$errors[]='Only your confirmed reservations can have a payment record.';if(!in_array($method,['Cash on pickup','Bank transfer (demo)','Demo record'],true))$errors[]='Choose a valid payment method.';if(!$errors){$exists=db()->prepare("SELECT id FROM payments WHERE reservation_id=? AND status='recorded'");$exists->execute([$rid]);if($exists->fetch())$errors[]='A payment record already exists for this reservation.';else{$tx='DEMO-'.strtoupper(bin2hex(random_bytes(4)));$p=db()->prepare("INSERT INTO payments (reservation_id,customer_id,car_id,transaction_id,transaction_type,amount,status) VALUES (?,?,?,?,?,?,'recorded')");$p->execute([$rid,$uid,$res['car_id'],$tx,$method,$res['total_amount']]);log_activity('Recorded demo payment for reservation #'.$rid);flash('success','Demo payment record saved. No real money was collected.');redirect('payments.php');}}}
$s=db()->prepare("SELECT r.*,c.name AS car_name FROM reservations r JOIN cars c ON c.id=r.car_id WHERE r.customer_id=? AND r.status='confirmed' ORDER BY r.created_at DESC");$s->execute([$uid]);$confirmed=$s->fetchAll();$p=db()->prepare('SELECT * FROM payments WHERE customer_id=? ORDER BY created_at DESC');$p->execute([$uid]);$payments=$p->fetchAll();require __DIR__.'/includes/header.php'; ?>
<section class="page-hero page-hero-compact"><div class="container"><span class="eyebrow">PAYMENT RECORDS</span><h1>Clear records, <span class="text-gradient">no surprises.</span></h1><p>This project uses demo payment records only. It does not process real card payments.</p></div></section><section class="section"><div class="container two-col-panels"><section class="panel"><h2>Record a payment</h2><div class="alert alert-warning">Academic demo only — no real payment gateway or card data is used.</div><?php if($errors): ?><div class="alert alert-danger"><ul><?php foreach($errors as $er): ?><li><?= e($er) ?></li><?php endforeach; ?></ul></div><?php endif; ?><?php if(!$confirmed): ?><p class="muted">You have no confirmed reservations awaiting a payment record.</p><?php else: ?><form method="post" class="form-stack"><?= csrf_field() ?><label>Confirmed reservation<select required name="reservation_id"><option value="">Select reservation</option><?php foreach($confirmed as $r): ?><option value="<?= (int)$r['id'] ?>">#<?= (int)$r['id'] ?> — <?= e($r['car_name']) ?> — <?= money($r['total_amount']) ?></option><?php endforeach; ?></select></label><label>Payment method<select name="method"><option>Demo record</option><option>Cash on pickup</option><option>Bank transfer (demo)</option></select></label><button class="btn btn-primary">Save demo record</button></form><?php endif; ?></section><section class="panel"><h2>Transaction history</h2><?php if(!$payments): ?><p class="muted">No payment records yet.</p><?php else: foreach($payments as $p): ?><div class="list-row"><span class="list-icon">₨</span><div class="list-main"><b><?= e($p['transaction_type']) ?></b><small><?= e($p['transaction_id']) ?> · <?= e($p['created_at']) ?></small></div><strong><?= money($p['amount']) ?></strong></div><?php endforeach; endif; ?></section></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
